import re

def check(output, reference, input) -> tuple[float, str]:
    try:
        # Normalize reference
        if isinstance(reference, dict):
            ref_label = str(reference.get("label", reference.get("reference", ""))).strip().lower()
        else:
            ref_label = str(reference).strip().lower()

        # Normalize output: strip whitespace, code fences, trailing punctuation, lowercase
        out_text = str(output).strip()
        # Remove markdown code fences
        out_text = re.sub(r'^```[\w]*\n?', '', out_text)
        out_text = re.sub(r'\n?```$', '', out_text)
        out_text = out_text.strip()
        # Remove trailing punctuation and whitespace
        out_text = out_text.rstrip(' .,;:!?')
        out_label = out_text.lower()

        # Allowed labels
        allowed = {'spam', 'ham'}

        # Check if output label is valid
        if out_label not in allowed:
            return 0.0, f"Invalid label: '{out_text}' (allowed: spam, ham)"

        # Check correctness
        if out_label == ref_label:
            return 1.0, "Correct"
        else:
            return 0.0, f"Incorrect: expected '{ref_label}', got '{out_label}'"

    except Exception as e:
        return 0.0, f"Parse error: {e}"

